  "content": "1|import type { DesignerVersionRecord, DesignerVersionSummary } from '../../../shared/api/queries/component-designer';
2|import {
3|  NEW_LAYOUT_PRESETS,
4|  createStableStateFromNewLayoutPreset,
5|} from './newLayoutPresets';
6|import { isBuiltInShellPresetId, type NewLayoutPresetId } from './types';
7|import { DEFAULT_DRAFT_FOLDER, isSystemManagedShellLayoutDraft } from '../../../shared/lib/designerShellEntry';
8|import { normalizeDesignerComponentName } from '../../../shared/lib/designerIdentity';
9|import { parseDesignerComponentPath } from '../../../shared/lib/designerComponentPath';
10|
11|const BUILT_IN_COMPONENT_EPOCH = '2024-01-01T00:00:00.000Z';
12|const BUILT_IN_COMPONENT_PREFIX = 'builtin-';
13|
14|/** Virtual folder for layout starter templates. Copy sources only — not live portal skins. */
15|export const LAYOUT_TEMPLATE_FOLDER = 'templates';
16|
17|export const catalogFolderForBuiltInPreset = (presetId: NewLayoutPresetId): string => (
18|  isBuiltInShellPresetId(presetId) ? DEFAULT_DRAFT_FOLDER : LAYOUT_TEMPLATE_FOLDER
19|);
20|
21|/** Former admin-page mock ids (`builtin-page-*`). Callers must reject these; they are not in the catalog. */
22|const LEGACY_BUILT_IN_ADMIN_PAGE_PREFIX = 'builtin-page-';
23|
24|export const isBuiltInComponentId = (componentId: string): boolean => componentId.startsWith(BUILT_IN_COMPONENT_PREFIX);
25|
26|export const toBuiltInComponentId = (presetId: NewLayoutPresetId): string => `${BUILT_IN_COMPONENT_PREFIX}${presetId}`;
27|
28|export const getBuiltInPresetId = (componentId: string): NewLayoutPresetId | null => {
29|  if (!isBuiltInComponentId(componentId) || componentId.startsWith(LEGACY_BUILT_IN_ADMIN_PAGE_PREFIX)) {
30|    return null;
31|  }
32|
33|  const presetId = componentId.slice(BUILT_IN_COMPONENT_PREFIX.length) as NewLayoutPresetId;
34|  return NEW_LAYOUT_PRESETS.some((preset) => preset.id === presetId) ? presetId : null;
35|};
36|
37|const listLayoutPresetSummaries = (): DesignerVersionSummary[] => (
38|  NEW_LAYOUT_PRESETS
39|    .filter((preset) => preset.id !== 'blank')
40|    .map((preset) => ({
41|      id: toBuiltInComponentId(preset.id),
42|      name: preset.id,
43|      folder: catalogFolderForBuiltInPreset(preset.id),
44|      createdAt: BUILT_IN_COMPONENT_EPOCH,
45|      updatedAt: BUILT_IN_COMPONENT_EPOCH,
46|      createdBy: 'system',
47|      updatedBy: 'system',
48|      isBuiltIn: true,
49|    }))
50|);
51|
52|export const listBuiltInComponentSummaries = (): DesignerVersionSummary[] => (
53|  listLayoutPresetSummaries()
54|);
55|
56|export const getBuiltInComponentRecord = (componentId: string): DesignerVersionRecord | null => {
57|  const presetId = getBuiltInPresetId(componentId);
58|  if (!presetId) {
59|    return null;
60|  }
61|
62|  const preset = NEW_LAYOUT_PRESETS.find((item) => item.id === presetId);
63|  if (!preset) {
64|    return null;
65|  }
66|
67|  const { state } = createStableStateFromNewLayoutPreset(presetId, componentId, preset.id);
68|
69|  return {
70|    id: componentId,
71|    name: preset.id,
72|    folder: catalogFolderForBuiltInPreset(presetId),
73|    document: state.document,
74|    bindingDefinitions: state.bindingDefinitions,
75|    metadata: {
76|      createdAt: BUILT_IN_COMPONENT_EPOCH,
77|      updatedAt: BUILT_IN_COMPONENT_EPOCH,
78|      createdBy: 'system',
79|      updatedBy: 'system',
80|    },
81|  };
82|};
83|
84|export const getBuiltInComponentRecordByName = (componentLookup: string): DesignerVersionRecord | null => {
85|  const trimmed = componentLookup.trim();
86|  if (!trimmed) {
87|    return null;
88|  }
89|
90|  const parsedPath = parseDesignerComponentPath(trimmed);
91|  const lookupKey = normalizeDesignerComponentName(parsedPath?.componentName ?? trimmed);
92|  if (!lookupKey) {
93|    return null;
94|  }
95|
96|  const summary = listBuiltInComponentSummaries().find(
97|    (item) => normalizeDesignerComponentName(item.name) === lookupKey,
98|  );
99|
100|  return summary ? getBuiltInComponentRecord(summary.id) : null;
101|};
102|
103|export const isLayoutTemplateSummary = (
104|  item: Pick<DesignerVersionSummary, 'isBuiltIn' | 'folder' | 'name'>,
105|): boolean => {
106|  if (isBuiltInShellPresetId(item.name)) {
107|    return false;
108|  }
109|
110|  return Boolean(item.isBuiltIn) || item.folder?.trim() === LAYOUT_TEMPLATE_FOLDER;
111|};
112|
113|/** Saved drafts + package UI + built-in shells in `general`, plus copy starters in `templates`. */
114|export const mergeComponentsCatalog = (
115|  customItems: DesignerVersionSummary[],
116|): DesignerVersionSummary[] => {
117|  const customOnly = customItems.filter(
118|    (item) => !item.isBuiltIn && !isSystemManagedShellLayoutDraft(item),
119|  );
120|  const customIds = new Set(customOnly.map((item) => item.id));
121|  const customNames = new Set(
122|    customOnly.map((item) => normalizeDesignerComponentName(item.name)),
123|  );
124|  const templateItems = listBuiltInComponentSummaries().filter((item) => (
125|    !customIds.has(item.id)
126|    && !customNames.has(normalizeDesignerComponentName(item.name))
127|  ));
128|  const normalizedCustomItems = customOnly.map((item) => ({
129|    ...item,
130|    folder: item.folder?.trim() ? item.folder.trim().toLowerCase() : 'general',
131|    isBuiltIn: false,
132|  }));
133|
134|  return [...templateItems, ...normalizedCustomItems].sort((left, right) => {
135|    const byUpdatedAt = (right.updatedAt ?? '').localeCompare(left.updatedAt ?? '');
136|    if (byUpdatedAt !== 0) {
137|      return byUpdatedAt;
138|    }
139|
140|    return left.id.localeCompare(right.id);
141|  });
142|};
143|"
}
